// apps/medusa/src/modules/shopping-inquiry/models/inquiry.ts
// Inquiry entity — stores pre-sale inquiry submissions from the ChatPanel form.
//
// Fields:
//   id              — ULID primary key (auto-generated by Medusa framework)
//   ref             — Human-readable reference, e.g. "ZLF-1705312345-ABC1"
//                     (prefix is per-tenant — see SHOPPING_REF_PREFIX)
//   status          — Lifecycle: new → reviewed → quoted → closed | spam
//   customer_name   — Submitter's name
//   customer_email  — Email address (mutually exclusive with whatsapp, but both may be set)
//   whatsapp        — WhatsApp number including country code (optional)
//   contact_method  — "email" | "whatsapp" — preferred contact channel
//   product_desc    — Free-text product description / standards / drawings info
//   material        — Material preference (optional free text)
//   quantity        — Numeric quantity requested
//   quantity_unit   — "pcs" | "kg" | "sets"
//   country         — Delivery destination country (ISO 3166-1 alpha-2)
//   special         — Special requirements (optional free text)
//   product_slug    — Product slug if inquiry originated from a product page (optional)
//   locale          — Visitor's language at time of submission (en | de | es | it | zh)
//   ip_hash         — SHA-256 hash of submitter IP for rate-limit enforcement (never stored raw)
//   admin_notes     — Internal notes added by owner/admin
//   created_at      — Auto-set on insert
//   updated_at      — Auto-set on update
//
// Reference: ai/todo.md Phase 3 §3.9 / Phase 5

import { model } from "@medusajs/framework/utils";

// ---------------------------------------------------------------------------
// Status enum
// ---------------------------------------------------------------------------

export const InquiryStatus = {
	NEW: "new",
	REVIEWED: "reviewed",
	QUOTED: "quoted",
	CLOSED: "closed",
	SPAM: "spam",
} as const;

export type InquiryStatusValue =
	(typeof InquiryStatus)[keyof typeof InquiryStatus];

// ---------------------------------------------------------------------------
// Contact method enum
// ---------------------------------------------------------------------------

export const ContactMethod = {
	EMAIL: "email",
	WHATSAPP: "whatsapp",
} as const;

export type ContactMethodValue =
	(typeof ContactMethod)[keyof typeof ContactMethod];

// ---------------------------------------------------------------------------
// Quantity unit enum
// ---------------------------------------------------------------------------

export const QuantityUnit = {
	PCS: "pcs",
	KG: "kg",
	SETS: "sets",
} as const;

export type QuantityUnitValue =
	(typeof QuantityUnit)[keyof typeof QuantityUnit];

// ---------------------------------------------------------------------------
// Supported locales
// ---------------------------------------------------------------------------

export const SupportedLocale = {
	EN: "en",
	DE: "de",
	ES: "es",
	IT: "it",
	ZH: "zh",
} as const;

export type SupportedLocaleValue =
	(typeof SupportedLocale)[keyof typeof SupportedLocale];

// ---------------------------------------------------------------------------
// Inquiry model
// ---------------------------------------------------------------------------

const Inquiry = model.define("inquiry", {
	// ── Primary key ─────────────────────────────────────────────────────────
	id: model.id().primaryKey(),

	// ── Human-readable reference ─────────────────────────────────────────────
	// Format: {SHOPPING_REF_PREFIX}-{unix_ts_seconds}-{4_random_chars}
	// Shown to customers in confirmation emails and the admin panel.
	// ref: model.text().searchable(),
	ref: model.text(),

	// ── Lifecycle status ─────────────────────────────────────────────────────
	status: model
		.enum(Object.values(InquiryStatus) as [string, ...string[]])
		.default(InquiryStatus.NEW),

	// ── Contact information ───────────────────────────────────────────────────
	// customer_name: model.text().searchable(),
	customer_name: model.text(),

	// Email and WhatsApp are both optional individually but validated so that
	// at least one of them is present (enforced in the API route, not the DB).
	// customer_email: model.text().nullable().searchable(),
	customer_email: model.text().nullable(),
	whatsapp: model.text().nullable(),

	// Which channel does the customer prefer for our reply?
	contact_method: model
		.enum(Object.values(ContactMethod) as [string, ...string[]])
		.default(ContactMethod.EMAIL),

	// ── Inquiry details ───────────────────────────────────────────────────────
	// Full product description including standards, drawings, specifications.
	// Stored as a text column — may be long (multi-paragraph).
	product_desc: model.text(),

	// Material preference (e.g. "A2 stainless steel", "HDG carbon steel")
	material: model.text().nullable(),

	// Quantity — stored as a string to preserve user input ("5,000" / "~500" etc.)
	// Numeric validation is done on the API layer; we store the raw string here
	// so no information is lost for the owner.
	quantity: model.text().nullable(),

	quantity_unit: model
		.enum(Object.values(QuantityUnit) as [string, ...string[]])
		.default(QuantityUnit.PCS),

	// ── Delivery context ──────────────────────────────────────────────────────
	// ISO 3166-1 alpha-2 country code (e.g. "DE", "US", "CN")
	country: model.text().nullable(),

	// Free-text special requirements (surface treatment, certifications, etc.)
	special: model.text().nullable(),

	// ── Origin context ────────────────────────────────────────────────────────
	// Product page slug if the inquiry came from a specific product
	product_slug: model.text().nullable(),

	// Visitor's UI language at submission time
	locale: model
		.enum(Object.values(SupportedLocale) as [string, ...string[]])
		.default(SupportedLocale.EN),

	// ── Anti-abuse ────────────────────────────────────────────────────────────
	// SHA-256 hash of the submitter's IP address.
	// Used for rate limiting (3 per IP per 24h).
	// NEVER store the raw IP address — this field is for abuse detection only.
	ip_hash: model.text().nullable(),

	// ── Admin fields ──────────────────────────────────────────────────────────
	// Internal notes added by the owner after reviewing the inquiry.
	admin_notes: model.text().nullable(),
});

export default Inquiry;
